1	// EQ Bank CSV Parser
2	// Expected format: Date,Description,Amount[,Balance]
3	// Date format: Supports both old (DD MMM YYYY, e.g., "06 Dec 2024") and new (YYYY-MM-DD, e.g., "2024-12-06")
4	// Amount: With dollar sign, can have parentheses for negative (e.g., "$0.10" or "($25.00)")
5	
6	import { BaseCSVParser } from './BaseCSVParser';
7	import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';
8	
9	export class EQBankParser extends BaseCSVParser {
10		parse(csvContent: string): CSVParseResult {
11			const transactions: ParsedTransaction[] = [];
12			const errors: string[] = [];
13	
14			try {
15				csvContent = this.removeBOM(csvContent);
16				const rows = this.parseCSV(csvContent);
17	
18				if (rows.length < 2) {
19					errors.push('CSV file is empty or has no data rows');
20					return { transactions, errors };
21				}
22	
23				// Validate header
24				const header = rows[0];
25				if (!this.validateFormat(csvContent)) {
26					errors.push('Invalid EQ Bank CSV format. Expected columns: Date, Description, Amount');
27					return { transactions, errors };
28				}
29	
30				// Find column indices
31				const dateIdx = header.findIndex(
32					(h) => h.toLowerCase().includes('date') || h.toLowerCase() === 'transfer date'
33				);
34				const descriptionIdx = header.findIndex((h) => h.toLowerCase().includes('description'));
35				const amountIdx = header.findIndex((h) => h.toLowerCase().includes('amount'));
36	
37				if (dateIdx === -1 || descriptionIdx === -1 || amountIdx === -1) {
38					errors.push('Could not find required columns in CSV header');
39					return { transactions, errors };
40				}
41	
42				// Parse data rows
43				for (let i = 1; i < rows.length; i++) {
44					const row = rows[i];
45					if (row.length < 3) continue; // Skip incomplete rows
46	
47					const dateStr = row[dateIdx]?.trim();
48					const description = row[descriptionIdx]?.trim();
49					const amountStr = row[amountIdx]?.trim();
50	
51					// Skip empty rows
52					if (!dateStr && !description && !amountStr) continue;
53	
54					// Parse date
55					const transaction_date = this.parseDate(dateStr);
56					if (!transaction_date) {
57						errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
58						continue;
59					}
60	
61					// Parse amount (parentheses indicate negative)
62					const rawAmount = this.parseAmount(amountStr);
63					if (rawAmount === null) {
64						errors.push(`Row ${i + 1}: Invalid amount "${amountStr}"`);
65						continue;
66					}
67	
68					// EQ Bank uses negative for expenses — keep as-is (#{#trn2b})
69					const amount = this.normalizeAmount(rawAmount, false);
70	
71					// Validate description
72					if (!description) {
73						errors.push(`Row ${i + 1}: Missing vendor name/description`);
74						continue;
75					}
76	
77					transactions.push({
78						transaction_date,
79						vendor_name: description,
80						amount
81					});
82				}
83			} catch (e: any) {
84				errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
85			}
86	
87			return { transactions, errors };
88		}
89	
90		validateFormat(csvContent: string): boolean {
91			try {
92				csvContent = this.removeBOM(csvContent);
93				const rows = this.parseCSV(csvContent);
94				if (rows.length === 0) return false;
95	
96				const header = rows[0];
97				// Check for EQ Bank-specific columns
98				// Must have exactly 3 or 4 columns
99				if (header.length < 3 || header.length > 4) return false;
100	
101				// Accept either "Date" or "Transfer date" for the date column
102				const hasDate = header.some(
103					(h) => h.toLowerCase() === 'date' || h.toLowerCase() === 'transfer date'
104				);
105				const hasDescription = header.some((h) => h.toLowerCase() === 'description');
106				const hasAmount = header.some((h) => h.toLowerCase() === 'amount');
107	
108				// Should NOT have columns like "Type", "Card Holder Name", "Time" (which are PC Financial)
109				const hasPCFinancialColumns = header.some(
110					(h) =>
111						h.toLowerCase() === 'type' ||
112						h.toLowerCase().includes('card holder') ||
113						h.toLowerCase() === 'time'
114				);
115	
116				return hasDate && hasDescription && hasAmount && !hasPCFinancialColumns;
117			} catch {
118				return false;
119			}
120		}
121	}
