190		/**
191		 * Remove BOM (Byte Order Mark) if present
192		 */
193		protected removeBOM(content: string): string {
194			if (content.charCodeAt(0) === 0xfeff) {
195				return content.slice(1);
196			}
197			return content;
198		}
